/**
 * Shared pure renderer for the audit report panel (used by the browser app,
 * the node tests, and the DOM/text snapshot for the human review packet).
 * Zero DOM access — returns an HTML string.
 * Renders: summary block (cards + text), filter controls, per-rule grouped
 * summary chips, and the findings table (each row carries a "copy fix snippet"
 * button).
 */

import { groupByRule } from '../public/filter.js'
import { formatCounts, countTotal } from '../public/format.js'

export function escapeHtml(text) {
  return String(text)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
}

const SEVERITY_LABEL = { error: '错误', warn: '警告', info: '提示' }

/** Render the summary cards + summary text for a set of counts. */
export function renderSummaryBlock(summary) {
  const cards = ['error', 'warn', 'info'].map(sev => (
    `<div class="card card-${sev}"><span class="count" data-sev="${sev}">${summary[`${sev}s`] ?? 0}</span>`
    + `<span class="label">${SEVERITY_LABEL[sev] ?? sev}</span></div>`
  )).join('\n')
  return `<div id="summary-cards">${cards}</div>`
    + `<div id="summary-text">${formatCounts(summary)} · 共 ${countTotal(summary)} 条</div>`
}

/** Render the <tbody> content for a set of findings. */
export function renderFindingsRows(findings) {
  return findings.map(f => (
    `<tr class="row-${escapeHtml(f.severity)}" data-rule="${escapeHtml(f.rule)}" data-severity="${escapeHtml(f.severity)}">`
    + `<td>${escapeHtml(f.rule)}</td>`
    + `<td>${SEVERITY_LABEL[f.severity] ?? escapeHtml(f.severity)}</td>`
    + `<td>${escapeHtml(f.message)}</td>`
    + `<td>${escapeHtml(f.file ?? '')}</td>`
    + `<td><button type="button" class="copy" data-rule="${escapeHtml(f.rule)}" data-file="${escapeHtml(f.file ?? '')}">复制修复片段</button></td>`
    + `</tr>`
  )).join('\n')
}

/** Render per-rule grouped summary chips (R1(2) / R5(1) ...), severity desc. */
export function renderGroupSummary(findings) {
  const groups = groupByRule(findings)
  return groups.map(g => (
    `<span class="group-chip" data-rule="${escapeHtml(g.rule)}" data-sev="${escapeHtml(g.severity)}">${escapeHtml(g.rule)}(${g.count})</span>`
  )).join(' ')
}

/** Render the full panel into a single HTML fragment (no <html>/<body>). */
export function renderPanelHtml(report) {
  const findings = report.findings ?? []
  return `<h1>审计报告：${escapeHtml(report.pkg ?? '')} v${escapeHtml(report.version ?? '')}</h1>`
    + `<div id="summary">${renderSummaryBlock(report.summary)}</div>`
    + `<div id="filters">`
    + `<label>级别 <select id="level-filter">`
    + `<option value="all">全部</option>`
    + `<option value="warn">警告及以上</option>`
    + `<option value="error">仅错误</option>`
    + `</select></label>`
    + `<label>规则前缀 <input id="rule-filter" type="text" placeholder="如 R1"></label>`
    + `</div>`

